// Core mechanism uses Procedure Linkage Table (PLT) and Global Offset Table (GOT)

// Initial State (Unresolved)
// GOT[X] points back to PLT[N]'s internal resolver stub
GOT[func_entry] = Address_of_PLT_Stub

// 1. First Call (Slow Path)
func_call:
    JMP *GOT[func_entry]    // Jump to PLT Stub

// PLT Stub executes:
    PUSH relocation_ID
    JMP *GOT[2]             // Call Dynamic Linker (ld.so)

// Dynamic Linker Resolves Address:
    ld.so determines Real_Func_Address
    ld.so rewrites GOT[func_entry] = Real_Func_Address

// 2. Subsequent Calls (Fast Path)
func_call:
    JMP *GOT[func_entry]    // Jump directly to Real_Func_Address

// Benefits: Startup time reduced; memory saved if symbols unused.
